// ═══ WITHOUT volatile: thread may never see the update ═══
class StopFlag {
    boolean running = true;  // NOT volatile!

    void run() {
        while (running) {  // JIT may cache 'running' in CPU register!
            doWork();       // Loop runs FOREVER even after stop() is called!
        }
    }

    void stop() {
        running = false;  // Written to main memory, but reader thread
                          // may never read from main memory!
    }
}
// Thread-1: calls run() → JIT caches running=true in register → NEVER sees false!
// Thread-2: calls stop() → sets running=false in main memory
// Thread-1 loops FOREVER — visibility problem!

// ═══ WITH volatile: guaranteed visibility ═══
class StopFlag {
    volatile boolean running = true;  // volatile!

    void run() {
        while (running) {  // EVERY read goes to main memory!
            doWork();       // Sees false immediately after stop() is called.
        }
    }

    void stop() {
        running = false;  // Written to main memory AND
                          // all CPU caches invalidated!
    }
}
// Thread-1: reads 'running' from main memory EVERY iteration!
// Thread-2: writes false → Thread-1 sees it on next read!

// ═══ volatile does NOT make counter++ atomic! ═══
volatile int counter = 0;
// Thread-1: read(0) → increment → write(1)
// Thread-2: read(0) → increment → write(1)  ← LOST increment!
// volatile ensures each read/write goes to main memory
// but read-then-increment-then-write is STILL 3 separate operations!

// ═══ WHAT volatile GUARANTEES ═══
// 1. VISIBILITY: write to volatile → all threads see the new value
// 2. HAPPENS-BEFORE: everything before a volatile write is visible
//    to everything after the next volatile read of the same variable
// 3. ORDERING: volatile prevents instruction reordering across the barrier

// ═══ WHAT volatile DOES NOT GUARANTEE ═══
// 1. ATOMICITY: compound operations (++, check-then-act) are NOT atomic
// 2. MUTUAL EXCLUSION: multiple threads CAN access simultaneously

// ═══ WHEN TO USE volatile ═══
// (Recommended) Status flags: volatile boolean shutdown = false;
// (Recommended) One writer, many readers: volatile BigDecimal latestPrice;
// (Recommended) Double-checked locking: volatile Singleton instance;
// (Avoid) Counters: counter++ → use AtomicInteger
// (Avoid) Check-then-act: if (x > 0) x-- → use synchronized
