// ─── File: src/test/java/com/bank/volatile_demo/VolatileTest.java ───
package com.bank.volatile_demo;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class VolatileTest {

    // ═══ volatile flag: guaranteed visibility ═══
    static class MarketFeedProcessor {
        volatile boolean running = true;
        int messagesProcessed = 0;

        void process() {
            while (running) {  // volatile read — always from main memory!
                messagesProcessed++;
                Thread.yield();
            }
        }

        void stop() {
            running = false;  // volatile write — visible to all threads!
        }
    }

    @Test
    void volatileFlag_stopsThreadReliably() throws InterruptedException {
        MarketFeedProcessor processor = new MarketFeedProcessor();

        Thread worker = new Thread(processor::process);
        worker.start();
        Thread.sleep(100);  // let it process some messages

        processor.stop();  // set volatile flag
        worker.join(2000);  // should stop within 2 seconds

        assertThat(worker.isAlive()).isFalse();  // stopped!
        assertThat(processor.messagesProcessed).isGreaterThan(0);
    }

    // ═══ volatile does NOT make ++ atomic ═══
    @Test
    void volatile_notAtomic_lostIncrements() throws InterruptedException {
        // Can't make a local volatile — using AtomicInteger to demonstrate concept
        int[] volatileCounter = {0};  // simulates volatile (not actually volatile in test)
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                for (int j = 0; j < 1000; j++) {
                    volatileCounter[0]++;  // NOT atomic even if volatile!
                }
                latch.countDown();
            }).start();
        }
        latch.await();

        System.out.println("Expected: 100000, Actual: " + volatileCounter[0]);
        // Likely < 100000 — lost increments!
    }

    // ═══ FIX: AtomicInteger for counters ═══
    @Test
    void atomicInteger_noLostIncrements() throws InterruptedException {
        AtomicInteger counter = new AtomicInteger(0);
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                for (int j = 0; j < 1000; j++) {
                    counter.incrementAndGet();  // CAS — atomic!
                }
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(counter.get()).isEqualTo(100000);  // ALWAYS correct!
    }

    // ═══ volatile for one-writer-many-readers ═══
    @Test
    void volatilePrice_oneWriterManyReaders() throws InterruptedException {
        AtomicReference<String> latestPrice = new AtomicReference<>("100.00");
        // AtomicReference provides volatile semantics

        // One writer:
        Thread writer = new Thread(() -> {
            latestPrice.set("105.50");
        });

        // Many readers:
        String[] readValues = new String[5];
        writer.start();
        writer.join();

        for (int i = 0; i < 5; i++) {
            final int idx = i;
            Thread reader = new Thread(() -> readValues[idx] = latestPrice.get());
            reader.start();
            reader.join();
        }

        for (String v : readValues) {
            assertThat(v).isEqualTo("105.50");  // all readers see latest value!
        }
    }
}
